import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Coze Programming: build a low-code agent","description":"Official path: sign in to Coze Programming, create a low-code agent, write a persona, debug, then publish. Not Doubao chat. Not Trae.","frontmatter":{"title":"Coze Programming: build a low-code agent","description":"Official path: sign in to Coze Programming, create a low-code agent, write a persona, debug, then publish. Not Doubao chat. Not Trae.","domain":"product","tags":["agent-builder"],"role":"tutorial"},"headers":[],"relativePath":"products/coze/coze.md","filePath":"products/coze/coze.md","lastUpdated":1787110548000}'),i={name:"products/coze/coze.md"};function s(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="coze-programming-build-a-low-code-agent" tabindex="-1">Coze Programming: build a low-code agent <a class="header-anchor" href="#coze-programming-build-a-low-code-agent" aria-label="Permalink to &quot;Coze Programming: build a low-code agent&quot;">​</a></h1><blockquote><p>This is a <strong>tutorial</strong>. Finish it and you have a conversational low-code agent you can publish.</p><p>Plans and channels: <a href="./coze-cheatsheet.html">Cheatsheet</a>. Workflows / knowledge / CLI: <a href="./coze-cookbook.html">Cookbook</a>. Words: <a href="./coze-glossary.html">Glossary</a>.</p></blockquote><p>Goal: go from “I heard Coze can build bots” to “I published one.”</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Open <a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a> (China). International is <a href="https://www.coze.com/" target="_blank" rel="noreferrer">coze.com</a>. Do not mix accounts or channels.</li><li>A phone number or Douyin account (<a href="https://docs.coze.cn/guides_sign_up" target="_blank" rel="noreferrer">sign-up</a>).</li><li>No coding required. The official quick start says so.</li><li>Team / enterprise members must use their plan’s login entry.</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Tell Coze the workspace from Coze Programming the builder.</li><li>Create a low-code agent the official way.</li><li>Write a persona that actually constrains the model.</li><li>Reference plugins in the persona, or they may never run.</li><li>Preview before you publish.</li></ul><h2 id="step-0-open-the-right-site" tabindex="-1">Step 0: open the right site <a class="header-anchor" href="#step-0-open-the-right-site" aria-label="Permalink to &quot;Step 0: open the right site&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You think you are…</th><th>Open</th><th>Do not open</th></tr></thead><tbody><tr><td>Building an agent / workflow</td><td><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a></td><td>Doubao, Trae</td></tr><tr><td>Working with ready-made agents</td><td><a href="https://www.coze.cn/" target="_blank" rel="noreferrer">coze.cn</a></td><td>Not this tutorial</td></tr><tr><td>Reading docs</td><td><a href="https://docs.coze.cn/" target="_blank" rel="noreferrer">docs.coze.cn</a></td><td>Random 2024 Bot blogs</td></tr></tbody></table><p>Official docs still call the visual builder “an earlier version of Coze Programming,” but <strong>new low-code agents still start in Coze Programming</strong> (<a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>, <a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">guides_quickstart</a>).</p><p>Free personal plan is enough to try. Paid tiers: <a href="./coze-cheatsheet.html#plans-and-credits">Cheatsheet · plans</a>. Do not memorize prices.</p><h2 id="step-1-create-a-low-code-agent" tabindex="-1">Step 1: create a low-code agent <a class="header-anchor" href="#step-1-create-a-low-code-agent" aria-label="Permalink to &quot;Step 1: create a low-code agent&quot;">​</a></h2><p>These clicks match the official “build an AI assistant” (praise-bot) page:</p><ol><li>Sign in to <strong>Coze Programming</strong>.</li><li>Pick a workspace at the top. Click <strong>New project</strong>.</li><li>Under <strong>Low-code</strong>, click <strong>Agent development</strong>.</li><li>Name it and describe it. Use <strong>Generate</strong> next to the icon, or switch to <strong>AI create</strong>.</li><li>Confirm. The arrange page has: <ul><li>Left: <strong>Persona &amp; reply logic</strong></li><li>Center: <strong>Skills</strong> (plugins, workflows, knowledge)</li><li>Right: <strong>Preview &amp; debug</strong></li></ul></li></ol><p>Source: <a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">guides_quickstart</a>.</p><h2 id="step-2-write-a-persona-not-just-a-name" tabindex="-1">Step 2: write a persona, not just a name <a class="header-anchor" href="#step-2-write-a-persona-not-just-a-name" aria-label="Permalink to &quot;Step 2: write a persona, not just a name&quot;">​</a></h2><p>The persona applies to every session. Official advice: role, tone, and what it must refuse.</p><p>Official praise-bot sample:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Role</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a high-energy praise-and-encourage bot. Use warm language so people leave more confident.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Skills</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Skill 1: praise strengths</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When the user mentions a trait or action, find the strength and praise it.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> If they mention nothing, ask a question first, then praise.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Skill 2: encourage through difficulty</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When they mention a hard problem, encourage and give a concrete next step.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> If they seem low without saying why, ask, then encourage.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Skill 3: factual questions</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">If you cannot answer, call Search.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Limits</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Only praise and encourage. No negative judgment.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Stay inside the requested format.</span></span></code></pre></div><p>Use <strong>auto-optimize prompt</strong>, then read the result. Do not assume the rewrite is your intent.</p><p>Models, single vs multi-agent, Temperature: <a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">overview</a>, <a href="https://docs.coze.cn/guides_llm" target="_blank" rel="noreferrer">set the model</a>. Personal free / plus can use Doubao, DeepSeek, and similar. Enterprise can also use other Ark models. Copy names from the live console, not from old screenshots.</p><h2 id="step-3-add-skills-only-when-the-model-is-not-enough" tabindex="-1">Step 3: add skills only when the model is not enough <a class="header-anchor" href="#step-3-add-skills-only-when-the-model-is-not-enough" aria-label="Permalink to &quot;Step 3: add skills only when the model is not enough&quot;">​</a></h2><p>Official rule: if the model can do the job, stop at the persona. Add skills for search, PPT, or private manuals.</p><p>Official “Toutiao Search” steps for the praise bot:</p><ol><li>In Skills, click <strong>+</strong> next to <strong>Plugin</strong>.</li><li>Search <strong>头条搜索</strong> / Toutiao Search and <strong>Add</strong>.</li><li>In the persona, type <code>{</code> and <strong>reference</strong> the plugin. Without the reference, the agent may never call it.</li></ol><p>Opening lines, suggested questions, background images, and voice are UX, not capability. Knowledge and workflows live in the <a href="./coze-cookbook.html">Cookbook</a>.</p><h2 id="step-4-preview-then-publish" tabindex="-1">Step 4: preview, then publish <a class="header-anchor" href="#step-4-preview-then-publish" aria-label="Permalink to &quot;Step 4: preview, then publish&quot;">​</a></h2><p>Chat in <strong>Preview &amp; debug</strong> first.</p><p>Check:</p><ul><li>The model does not introduce itself as Doubao / DeepSeek if you named it something else.</li><li>Plugin questions actually hit the tool.</li><li>Refused topics stay refused.</li></ul><p>The debug pane shows the run. If production is slow or silent, look there before blaming the model.</p><h2 id="step-5-publish" tabindex="-1">Step 5: publish <a class="header-anchor" href="#step-5-publish" aria-label="Permalink to &quot;Step 5: publish&quot;">​</a></h2><p>Official steps:</p><ol><li><strong>Publish</strong> at the top right.</li><li>Write a release note and pick channels.</li><li><strong>Publish</strong> again.</li></ol><p>Default channels include the Coze store / community, Feishu, WeChat (customer service / service account / subscription), Juejin, Douyin / WeChat mini programs, API, and Chat SDK. Full table: <a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">publish overview</a> and the <a href="./coze-cheatsheet.html#publish-channels">cheatsheet</a>.</p><p><strong>Do not look for the Doubao channel.</strong> That low-code entry closed on <strong>2026-07-01</strong>. Already published agents stay up (<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>).</p><p>Publish packs the project, runs a Coze review, then a channel review. Failures go back to the on-screen hint and the <a href="https://docs.coze.cn/guides_content_principles" target="_blank" rel="noreferrer">content rules</a>.</p><p>Store and debug chats time out at <strong>10 minutes</strong> (“run aborted”). Shorten the workflow.</p><h2 id="alternate-path-full-code-agent" tabindex="-1">Alternate path: full-code agent <a class="header-anchor" href="#alternate-path-full-code-agent" aria-label="Permalink to &quot;Alternate path: full-code agent&quot;">​</a></h2><p>To say one sentence and let the platform write the agent:</p><ol><li>Open <a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a>.</li><li>Open the <strong>Agent</strong> tab.</li><li>Describe features, logic, and constraints. Submit.</li><li>Wait for the project and unit tests, then preview.</li></ol><p>This burns programming-task credits, built-in integrations, and hosting after deploy. Details: <a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">develop an agent</a> and the <a href="./coze-cookbook.html#generate-a-full-code-agent-with-ai-programming">Cookbook</a>.</p><p>AI programming inside Coze (coze.cn) <strong>cannot</strong> replace this for agents and workflows.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Agent calls itself Doubao / DeepSeek</td><td>Persona never overrode the default identity</td><td>Name the role in the persona</td></tr><tr><td>Plugin never runs</td><td>No <code>{</code> reference</td><td>Reference the tool</td></tr><tr><td>No Doubao channel</td><td>Closed 2026-07-01</td><td>Feishu / WeChat / API</td></tr><tr><td>“Run aborted” in debug</td><td>10-minute timeout</td><td>Shorten the workflow</td></tr><tr><td>Want to self-host Programming</td><td>Commercial cloud cannot</td><td>Use <a href="https://github.com/coze-dev/coze-studio" target="_blank" rel="noreferrer">Coze Studio</a></td></tr><tr><td>Landed in Doubao or Trae</td><td>Wrong product</td><td>Back to the <a href="./">map</a></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Knowledge or workflows: <a href="./coze-cookbook.html">Cookbook</a></li><li>Plans, CLI, channels: <a href="./coze-cheatsheet.html">Cheatsheet</a></li><li>Skill / plugin / workflow: <a href="./coze-glossary.html">Glossary</a></li></ul>`,47)])])}const b=t(i,[["render",s]]);export{f as __pageData,b as default};
